function optics(host){
 const objects=[];for(const[id,position,clear]of[['emitter',spec.optics.emitterPosition,true],['receiver',spec.optics.receiverPosition,false]]){const g=new THREE.Group();g.name=`Reflective IR fixed ${id} optical package`;g.position.fromArray(position);host.body.add(g);const resin=materials.plastic(clear?0xcfd6d2:0x080e0c,{roughness:clear?.17:.24,transparent:clear,opacity:clear?.48:1,depthWrite:!clear}),metal=materials.metal(0xb8bcae,{roughness:.38});mesh(g,new THREE.CylinderGeometry(2.5,2.5,1.7,64).rotateX(Math.PI/2),resin,[0,0,.85],`Reflective IR non-emissive ${id} resin barrel`);const dome=mesh(g,new THREE.SphereGeometry(2.5,64,32,0,tau,0,Math.PI/2).rotateX(Math.PI/2),resin,[0,0,1.7],`Reflective IR non-emissive ${id} optical dome`);mesh(g,new THREE.CylinderGeometry(2.65,2.65,.35,64).rotateX(Math.PI/2),materials.plastic(0x282e29,{roughness:.7}),[0,0,-.1],`Reflective IR fixed ${id} lens base flange`);for(const sign of[-1,1])mesh(g,new THREE.BoxGeometry(.5,.45,3.1),metal,[sign*1.27,0,-1.4],`Reflective IR physical ${id} package lead`);const die=mesh(g,new THREE.BoxGeometry(1.1,.9,.3),materials.plastic(0x26332b),[.5,0,.45],`Reflective IR passive ${id} internal die backing`);mesh(g,new THREE.BoxGeometry(.8,1.5,.2),metal,[-.6,0,.25],`Reflective IR ${id} leadframe cup`);objects.push({id,group:g,dome,die});host.add(new Component({id,label:`D${id==='emitter'?4:3} ${id} appearance anchor`,position,meta:{role:'visual-anchor',scope:'Passive package position only; no visible IR light/beam,light emission,sensing,ADC,distance,threshold or electrical commands'}}));}return objects;
}
function trimmer(host){
 const metal=materials.metal(0xa6b2aa,{roughness:.48}),body=slab(host.body,3.4,3.4,1.4,.22,[0,8,-2.55],materials.plastic(0xd4d9cf,{roughness:.79}),[],.04);body.name='Reflective IR R4 fixed 3313J trimmer body behind genuine access hole';for(const[x,y]of[[-1.5,-.8],[-1.5,.8],[1.5,0]]){mesh(host.body,new THREE.BoxGeometry(.7,.5,.35),metal,[x,8+y,-1.1],'Reflective IR R4 fixed solder terminal');mesh(host.body,new THREE.BoxGeometry(.5,.3,1.3),metal,[x,8+y,-.45],'Reflective IR R4 physical pin from rear package to PCB');}
 const cap=new THREE.Group();cap.name='Reflective IR R4 moving slotted head';cap.position.fromArray(spec.trimmer.position);host.body.add(cap);const circle=new THREE.Shape();circle.absarc(0,0,.66,0,tau,false);const slot=new THREE.Path();slot.moveTo(-.16,-.7);slot.lineTo(-.16,.7);slot.lineTo(.16,.7);slot.lineTo(.16,-.7);slot.closePath();
 // Two independent rounded cap halves leave a physical recessed screwdriver slot.
 for(const sign of[-1,1]){const s=new THREE.Shape(),a=Math.acos(.14/.66);if(sign>0){s.moveTo(.14,-Math.sqrt(.66**2-.14**2));s.absarc(0,0,.66,-a,a,false);s.closePath();}else{s.moveTo(-.14,Math.sqrt(.66**2-.14**2));s.absarc(0,0,.66,Math.PI-a,Math.PI+a,false);s.closePath();}extrude(cap,s,.22,[0,0,-.15],metal,'Reflective IR true slotted moving trimmer head half');}
 mesh(cap,new THREE.CylinderGeometry(.45,.45,1.4,48).rotateX(Math.PI/2),metal,[0,0,.8],'Reflective IR physical turning shaft into trimmer body');mesh(cap,new THREE.CylinderGeometry(.66,.66,.35,48).rotateX(Math.PI/2),materials.plastic(0x67756c,{roughness:.8}),[0,0,.12],'Reflective IR recessed trimmer slot floor and shaft');const threshold=host.add(new VisualJoint({id:'threshold',label:'R4 screwdriver head angle',position:spec.trimmer.position,axis:spec.trimmer.axis,limitsDeg:spec.trimmer.limitsDeg,meta:{role:'externally-driven-visual-joint',rangeEvidence:spec.trimmer.rangeEvidence,scope:'Externally requested finite angle/duration only; no pointer detection-distance setting,electrical threshold,resistance,ADC,comparator,LED coupling or firmware behavior'}}));threshold.adopt(cap);return{body,cap,threshold};
}
class RedStatusLed extends Led{set(state){if(typeof state==='boolean')state={on:state};else if(typeof state==='string'||typeof state==='number')state={on:true};super.set({...state,color:spec.statusLed.color});this.glow.visible=false;}}
function status(host){const lens=new THREE.Mesh(new THREE.BoxGeometry(1.6,.8,.5),materials.plastic(0xad3330,{roughness:.31}));lens.name='Reflective IR actual concealed D1 RED0603 package';return host.add(new RedStatusLed({id:'status-led',label:'D1 red status appearance',position:spec.statusLed.position,mesh:lens,color:spec.statusLed.color,glowSize:0,meta:{role:'externally-driven-indicator',fixedColor:'red',visibility:'Actual PCB LED is concealed by the assembled shell; no invented exterior aperture or halo.',scope:'Independent external on/brightness only. No AO/DO,sensor,trimmer or comparator coupling.'}}));}
function grove(host){const g=new THREE.Group();g.name='Reflective IR open black HY2.0-4P socket';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const plastic=materials.plastic(spec.grove.color,{roughness:.76}),metal=materials.metal(0xb9b8a5,{roughness:.43}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'Reflective IR Grove '+n),depth=6.3;for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-5.8],`tail ${i+1}`,metal);}const port=host.add(new Port({id:'grove',label:'PORT.B · I/O',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'DO',color:'yellow'},{n:4,name:'AO',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical attachment,four contacts and documented pin labels only; no voltage,ADC,GPIO,electrical or firmware model'}}));return{group:g,contacts,port};}
export function buildReflectiveIR(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.79})}),pcb=board(host),optical=optics(host),threshold=trimmer(host),led=status(host),input=grove(host),fixing=screw(host.body,[0,-4,-3.98],'back',1.35);fixing.name='Reflective IR actual fixed recessed hex retaining screw';mesh(host.body,new THREE.CylinderGeometry(.65,.65,4.8,32).rotateX(Math.PI/2),materials.metal(0xa0a49a),[0,-4,-.4],'Reflective IR concealed retaining screw shank');const anchor=host.add(new Component({id:'sensor',label:'Reflective IR passive sensor appearance anchor',position:[0,8,4],meta:{role:'visual-anchor',scope:'Passive appearance only; no IR rays,ADC,distance,threshold voltage,AO/DO,comparator,electrical or firmware commands'}}));host.reflectiveIRAssembly={parts,pcb,optical,trimmer:threshold,led,input,fixing,anchor};host.unitStickers=addStickers(host);}
